// Group items by recipe_ref
const grouped = {};

for (const item of $input.all()) {
  const recipeRef = item.json.recipe_ref;

  if (!grouped[recipeRef]) {
    grouped[recipeRef] = [];
  }
  grouped[recipeRef].push(item.json);
}

// Return as array of groups
return Object.entries(grouped).map(([recipeRef, items]) => ({
  json: {
    recipe_ref: recipeRef,
    items: items,
    count: items.length
  }
}));

const stdout = $input.first().json.stdout;

if (!stdout) {
  throw new Error('stdout is empty');
}

let parsed;

try {
  parsed = JSON.parse(stdout);
} catch (e) {
  throw new Error('stdout is not valid JSON:\n' + stdout);
}

// Eğer array dönüyorsa → n8n item formatına çevir
if (Array.isArray(parsed)) {
  return parsed.map(item => ({ json: item }));
}

// Eğer object ise direkt dön
return [{ json: parsed }];

const stdout = $input.first().json.stdout || '';

// JSON kısmını yakala (object)
const match = stdout.match(/\{[\s\S]*\}$/);

if (!match) {
  throw new Error('JSON not found in stdout:\n' + stdout);
}

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch (e) {
  throw new Error('Invalid JSON:\n' + match[0]);
}

// Genel başarı durumu
const jobSuccess = parsed.success;

// Sample bilgisi direkt yok → count var
// Ama senin önceki node’dan sample listesi geliyor olabilir
// Burada fallback olarak count kadar item üretelim

const samplesCount = parsed.samples_count || 0;

// Her sample için item üret
const items = [];

for (let i = 0; i < samplesCount; i++) {
  items.push({
    json: {
      job_id: parsed.job_id,
      job_name: parsed.job_name,
      success: jobSuccess,
      error: parsed.error,
      sample_index: i + 1,
      samples_count: samplesCount
    }
  });
}

return items;

